corrected_code:
const amqp = require('amqplib');

async function startRefundWorker() {
  const conn = await amqp.connect(process.env.RABBITMQ_URL);
  const channel = await conn.createChannel();
  await channel.assertQueue('payments.refund.queue', { durable: true });

  channel.consume('payments.refund.queue', async (msg) => {
    if (!msg) return;
    const data = JSON.parse(msg.content.toString());
    const { orderId, amountCents, requestedBy } = data;

    const order = await Order.findOne({
      where: { id: orderId, customerId: requestedBy }
    });
    if (!order) {
      console.warn(`Refund authorization check failed: order ${orderId} does not belong to ${requestedBy}`);
      channel.ack(msg);
      return;
    }

    if (order.paymentStatus === 'PAID') {
      await stripe.refunds.create({
        charge: order.stripeChargeId,
        amount: amountCents
      });
      await order.update({ paymentStatus: 'REFUNDED', refundIssuedAt: new Date() });
    }
    channel.ack(msg);
  });
}
